counter = {"done": 0, "total": 0}


def fetch(url, timeout=10, retries=2):
    last_exc = None
    for _ in range(retries):
        try:
            return requests.get(url, headers=HEADERS, timeout=timeout, verify=False, allow_redirects=True)
        except Exception as e:
            last_exc = e
            time.sleep(0.5)
    return last_exc


BAD_CANDIDATES = {
    "error", "403 forbidden", "404 not found", "not found", "forbidden",
    "invalid url", "無効なurlです", "無効なurl", "アクセスできません",
    "ページが見つかりません", "just a moment...", "attention required",
    "coming soon", "not implemented", "501 not implemented", "bad gateway",
    "service unavailable", "internal server error",
}
BAD_SUBSTR = ["forbidden", "not found", "error", "\\u", "just a moment", "503", "500 ", "404", "403"]
DOMAIN_LIKE = re.compile(r"^[a-z0-9.-]+\.(com|jp|net|co|info|biz|space|work|design|org)$", re.I)


def clean_candidate(s):
    s = html.unescape(s)
    s = s.strip(" 　\t\n-–—|｜:：")
    for w in STRIP_WORDS:
        s = re.sub(re.escape(w), "", s, flags=re.I).strip(" 　\t\n-–—|｜:：")
    return s.strip()


def refine_with_suffix(raw):
    """区切り文字を含む長い文字列は、法人格の付いた断片を優先して抜き出す。"""
    if not raw or len(raw) <= 20 or not SEPARATORS.search(raw):
        return raw
    parts = [clean_candidate(p) for p in SEPARATORS.split(raw)]
    parts = [p for p in parts if p and not is_bad(p)]
    for p in parts:
        if COMPANY_SUFFIX_HINT.search(p) and len(p) <= 30:
            return p
    return raw


def is_bad(cand):
    if not cand or len(cand) < 2:
        return True
    low = cand.lower()
    if low in BAD_CANDIDATES:
        return True
    if any(b in low for b in BAD_SUBSTR):
        return True
    if DOMAIN_LIKE.match(cand):
        return True
    return False


def find_jsonld_name(text):
    for m in re.finditer(
        r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', text, re.S | re.I
    ):
        raw = m.group(1).strip()
        try:
            obj = json.loads(raw)
        except Exception:
            continue
        candidates = obj if isinstance(obj, list) else [obj]
        stack = list(candidates)
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                if "@graph" in node and isinstance(node["@graph"], list):
                    stack.extend(node["@graph"])
                t = node.get("@type", "")
                types = t if isinstance(t, list) else [t]
                if any(str(x).lower() in ("organization", "corporation", "localbusiness") for x in types):
                    name = node.get("name")
                    if isinstance(name, str):
                        cand = clean_candidate(name)
                        if not is_bad(cand):
                            return cand
            elif isinstance(node, list):
                stack.extend(node)
    return ""


def extract_name(text):
    cand = find_jsonld_name(text)
    if cand:
        return cand, "jsonld"

    m = re.search(
        r'<meta[^>]+property=["\']og:site_name["\'][^>]+content=["\'](.*?)["\']', text, re.I | re.S
    )
    if not m:
        m = re.search(
            r'<meta[^>]+content=["\'](.*?)["\'][^>]+property=["\']og:site_name["\']', text, re.I | re.S
        )
    if m:
        cand = clean_candidate(m.group(1))
        if not is_bad(cand):
            return cand, "og:site_name"

    m = re.search(r"<title[^>]*>(.*?)</title>", text, re.S | re.I)
    if m:
        raw = html.unescape(re.sub(r"\s+", " ", m.group(1)).strip())
        parts = [clean_candidate(p) for p in SEPARATORS.split(raw)]
        parts = [p for p in parts if p and not is_bad(p)]
        for p in parts:
            if COMPANY_SUFFIX_HINT.search(p):
                return p, "title(suffix-match)"
        if parts and not is_bad(raw):
            return "", f"uncertain:{raw[:60]}"
    return "", "not-found"


def worker(row):
    idx, url = row
    if not url or not url.strip():
        return (idx, url, "", "no-url")
    u = url.strip()
    if not re.match(r"^https?://", u):
        u = "http://" + u
    resp = fetch(u)
    name, source = "", "fetch-failed"
    if not isinstance(resp, Exception):
        if resp.status_code >= 400:
            source = f"http-{resp.status_code}"
        else:
            try:
                if not resp.encoding or resp.encoding.lower() in ("iso-8859-1", "ascii"):
                    resp.encoding = resp.apparent_encoding
                text = resp.text
                name, source = extract_name(text)
            except Exception as e:
                source = f"error:{type(e).__name__}"
    else:
        source = f"error:{type(resp).__name__}"

    with lock:
        counter["done"] += 1
        if counter["done"] % 25 == 0 or counter["done"] == counter["total"]:
            with open(PROGRESS, "w") as pf:
                pf.write(f"{counter['done']}/{counter['total']}\n")

    return (idx, url, name, source)


def main():
    with open(SRC, encoding="utf-8-sig") as f:
        rows = list(csv.reader(f))
    header, data = rows[0], rows[1:]

    tasks = [(i, r[1] if len(r) > 1 else "") for i, r in enumerate(data) if not r[0].strip()]
    counter["total"] = len(tasks)

    with open(OUT, "w", newline="", encoding="utf-8-sig") as outf:
        w = csv.writer(outf)
        w.writerow(["idx", "url", "name_guess", "source"])
        with ThreadPoolExecutor(max_workers=40) as ex:
            futures = [ex.submit(worker, t) for t in tasks]
            for fut in as_completed(futures):
                res = fut.result()
                w.writerow(res)
                outf.flush()

    with open(PROGRESS, "w") as pf:
        pf.write(f"DONE {counter['total']}/{counter['total']}\n")


if __name__ == "__main__":
    main()
